import{_ as e,c as n,o as s,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Community Skills Exchange","description":"","frontmatter":{"title":"Community Skills Exchange"},"headers":[],"relativePath":"community/community-skills-exchange.md","filePath":"community/community-skills-exchange.md","lastUpdated":null}'),l={name:"community/community-skills-exchange.md"};function i(o,a,t,p,c,u){return s(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="community-skills-exchange" tabindex="-1">Community Skills Exchange <a class="header-anchor" href="#community-skills-exchange" aria-label="Permalink to &quot;Community Skills Exchange&quot;">​</a></h1><h2 id="community-skills-exchange-1" tabindex="-1">Community Skills Exchange <a class="header-anchor" href="#community-skills-exchange-1" aria-label="Permalink to &quot;Community Skills Exchange&quot;">​</a></h2><h3 id="individuals-offering-skills-or-freelance-services" tabindex="-1">Individuals Offering Skills or Freelance Services <a class="header-anchor" href="#individuals-offering-skills-or-freelance-services" aria-label="Permalink to &quot;Individuals Offering Skills or Freelance Services&quot;">​</a></h3><p>If you are interested in contributing to the community, volunteering your skills, or offering freelance services, this is the place to post what you can help with.</p><p>If you are looking for a Job Posting from the community see <a href="/community/community-job-announcements.html">Job Announcements</a></p><h3 id="current-skills-offered" tabindex="-1">Current Skills Offered <a class="header-anchor" href="#current-skills-offered" aria-label="Permalink to &quot;Current Skills Offered&quot;">​</a></h3><p>Available on the Forum: <a href="https://forum.irregularchat.com/tag/skills-offered" target="_blank" rel="noreferrer">Skills Offered Tag</a></p><h3 id="guidelines-for-posting-your-skills-or-services" tabindex="-1">Guidelines for Posting Your Skills or Services <a class="header-anchor" href="#guidelines-for-posting-your-skills-or-services" aria-label="Permalink to &quot;Guidelines for Posting Your Skills or Services&quot;">​</a></h3><p>If you would like to offer your skills for free, or as a freelancer, post it <a href="https://forum.irregularchat.com/tag/skills-offered" target="_blank" rel="noreferrer">here</a>.</p><h2 id="you-must-be-logged-into-irregularchat-sso" tabindex="-1">You must be logged into <a href="https://sso.irregularchat.com" target="_blank" rel="noreferrer">IrregularChat SSO</a>. <a class="header-anchor" href="#you-must-be-logged-into-irregularchat-sso" aria-label="Permalink to &quot;You must be logged into [IrregularChat SSO](https://sso.irregularchat.com).&quot;">​</a></h2><h2 id="add-a-new-topic-to-the-community-forum-category" tabindex="-1">Add a new topic to the <a href="https://forum.irregularchat.com/c/off-topic-guild/community-only/7" target="_blank" rel="noreferrer">community forum category</a>. <a class="header-anchor" href="#add-a-new-topic-to-the-community-forum-category" aria-label="Permalink to &quot;Add a new topic to the [community forum category](https://forum.irregularchat.com/c/off-topic-guild/community-only/7).&quot;">​</a></h2><h2 id="add-skills-offered-as-a-tag" tabindex="-1">Add &quot;skills offered&quot; as a tag. <a class="header-anchor" href="#add-skills-offered-as-a-tag" aria-label="Permalink to &quot;Add &quot;skills offered&quot; as a tag.&quot;">​</a></h2><h2 id="use-the-template-below-or-a-similar-format-to-provide-details" tabindex="-1">Use the template below or a similar format to provide details. <a class="header-anchor" href="#use-the-template-below-or-a-similar-format-to-provide-details" aria-label="Permalink to &quot;Use the template below or a similar format to provide details.&quot;">​</a></h2><h2 id="once-you-are-no-longer-available-please-edit-your-post-to-indicate-that-you-are-unavailable" tabindex="-1">Once you are no longer available, please <em>edit your post to indicate that you are unavailable.</em> <a class="header-anchor" href="#once-you-are-no-longer-available-please-edit-your-post-to-indicate-that-you-are-unavailable" aria-label="Permalink to &quot;Once you are no longer available, please *edit your post to indicate that you are unavailable.*&quot;">​</a></h2><h3 id="template-for-offering-skills-to-the-community" tabindex="-1">Template for Offering Skills to the Community <a class="header-anchor" href="#template-for-offering-skills-to-the-community" aria-label="Permalink to &quot;Template for Offering Skills to the Community&quot;">​</a></h3><p>This is in markdown syntax, so the forum can be rendered properly.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. TITLE:</span></span>
<span class="line"><span>Available for [(e.g., &quot;Available for Graphic Design, Web Development, Writing&quot;)</span></span>
<span class="line"><span>   1. Location:</span></span>
<span class="line"><span>[City/Country](Skill/Service]) OR REMOTE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. Services Offered:</span></span>
<span class="line"><span>Briefly describe the skills or services you can provide.</span></span>
<span class="line"><span>- E.g., Graphic design, coding, writing, research, tutoring, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. Availability:</span></span>
<span class="line"><span>Days and times when you are available to help or work.</span></span>
<span class="line"><span>- E.g., &quot;Weekdays after 5 PM EST,&quot; &quot;Available weekends only,&quot; or &quot;Flexible schedule.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. Experience/Qualifications:</span></span>
<span class="line"><span>(Optional) Share your background, relevant experience, or certifications.</span></span>
<span class="line"><span>- E.g., &quot;5+ years of graphic design experience,&quot; &quot;Certified AWS Solutions Architect,&quot; etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. Rates:</span></span>
<span class="line"><span>If offering freelance services, mention your rates (hourly/project-based).</span></span>
<span class="line"><span>- E.g., &quot;Negotiable,&quot; &quot;Starting at $50/hour,&quot; &quot;Pro bono for community projects,&quot; etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   1. POC:</span></span>
<span class="line"><span>Preferred contact method (e.g., email, forum direct message).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div>`,17)])])}const h=e(l,[["render",i]]);export{d as __pageData,h as default};
